const input = $input.first().json.body || $input.first().json;

const orderId = input.orderId || ('AOS-' + Math.floor(100000 + Math.random() * 900000));
const storeName = input.storeName || 'Retail Customer';
const contactPerson = input.contactPerson || storeName;
const deliveryArea = input.deliveryArea || 'Madurai Market';
const phone = input.phone || '';
const items = input.items || [];
const totalEstimatedValue = input.totalEstimatedValue || '₹0';
const remarks = input.remarks || 'Standard lorry dispatch';

// Format items for WhatsApp
let itemsFormatted = '';
if (Array.isArray(items) && items.length > 0) {
  itemsFormatted = items.map(it => {
    const name = it.productName || it.name || 'Gold Winner Oil';
    const size = it.packSize || '';
    const qty = it.boxQuantity || it.quantity || 1;
    const rate = it.boxRate ? (' @ ₹' + it.boxRate) : '';
    return `• ${qty}x ${name} (${size})${rate}`;
  }).join('\n');
} else {
  itemsFormatted = '• 1 Box Gold Winner Oil';
}

// Message to Retailer
const retailerMsg = `📦 *அண்ணாமலையார் ஆயில் ஸ்டோர் - ஆர்டர் உறுதி செய்யப்பட்டது!*\n\n` +
  `வணக்கம் ${contactPerson} அண்ணா (${storeName})!\n` +
  `உங்கள் மொத்த ஆர்டர் வெற்றிகரமாக பதிவு செய்யப்பட்டுள்ளது.\n\n` +
  `📋 *ஆர்டர் விபரம் (Order ID: ${orderId}):*\n` +
  `${itemsFormatted}\n\n` +
  `💰 *மதிப்பிடப்பட்ட மொத்த தொகை:* ${totalEstimatedValue}\n` +
  `🚚 *டெலிவரி இடம்:* ${deliveryArea}\n` +
  `⏰ *லாரி லோடிங்:* இன்று மதியம் 2:00 மணி (மாட்டுத்தாவணி மார்க்கெட்)\n\n` +
  `பிரபு அண்ணா உங்கள் ஆர்டரை லோடிங் செய்ய ஏற்பாடு செய்து வருகிறார். ஏதேனும் சந்தேகம் இருந்தால் தொடர்பு கொள்ளவும்! 🙏`;

// Urgent Alert to Prabhu Anna (Owner)
const ownerAlert = `🚨 *புதிய மொத்த ஆர்டர் வந்துள்ளது! (New Wholesale Order)*\n\n` +
  `🏪 *கடை:* ${storeName} (${deliveryArea})\n` +
  `👤 *தொடர்பு:* ${contactPerson} (${phone})\n` +
  `📋 *பொருட்கள்:*\n${itemsFormatted}\n\n` +
  `💵 *பில் மதிப்பு:* ${totalEstimatedValue}\n` +
  `🚛 *டெஸ்க்பாட்ச்:* இன்று மதியம் 2 மணி லாரி லோடிங்\n` +
  `🔖 *Order ID:* ${orderId}`;

return [{
  json: {
    orderId,
    storeName,
    contactPerson,
    phone,
    deliveryArea,
    totalEstimatedValue,
    retailerMsg,
    ownerAlert,
    timestamp: new Date().toISOString()
  }
}];
